// New definitions retain the rendering and pathfinding of the existing RTS.
function define(type,base,props){DEF[type]={...clone(DEF[base]),...props};BASE_DEF[type]=clone(DEF[type]);SHORT[type]=DEF[type].name;IC[type]=IC[base]||IC.temple}
