define('companion','spearman',{name:'Story companion',hero:1,hp:500,atk:22,pop:0,cost:undefined,desc:'A hero of this memory. Ariel protects the people; he cannot change fate.'});
define('priest','villager',{name:'Priest',cls:'priest',atk:0,cost:{food:80,gold:30},time:14,desc:'Prays beside a completed Temple to generate 0.6 Glory per second.'});
define('caravan','horseman',{name:'Trade Caravan',cls:'trade',atk:0,hp:160,cost:{wood:80,gold:50},time:18,desc:'Travels between your Market and a distant trade post to earn gold.'});
define('ram','horseman',{name:'Siege Ram',hp:650,atk:30,rof:2,spd:26,age:3,cls:'siege',bonus:{bld:5},cost:{wood:200,gold:130},time:30,desc:'Slow siege weapon. Strong against buildings.'});
