define('market','stable',{name:'Market',age:2,trains:['caravan'],cost:{wood:180,gold:80},desc:'Exchange resources and train trade caravans.'});
define('library','temple',{name:'Library',age:2,farr:0,trains:[],desc:'Preserves the writing taught by the captured demons.'});
define('observatory','tower',{name:'Observatory',age:2,atk:0,cost:{wood:200,gold:200},desc:'A place for stargazers to study the heavens.'});
define('nest','temple',{name:'Simurgh’s Nest',age:3,trains:['simurgh','dragon'],farr:0,cost:{wood:200,gold:150},desc:'Calls mythic flying allies.'});
