const bAliases={cave:'store',range:'barracks',blacksmith:'store',market:'stable',library:'temple',observatory:'tower',nest:'temple',wonder:'palace',wall:'store',gate:'wall',stronghold:'palace',lair:'pit',tradepost:'store'};
for(const [t,a] of Object.entries(bAliases))BUILD[t]=BUILD[a];
const originalHumanSpec=humanSpec, originalUnitModel=unitModel, originalAnimUnit=animUnit;
humanSpec=function(type,team){if(type==='ariel')return{tunic:0x183f53,trim:0xdfb656,pants:0x252b36,hair:0x211b16,beard:0x302017,cape:0x285668,skin:0xb58260,heroTrim:1,tools:['w_sword'],wk:'sword',scale:1.13};if(type==='companion')return{...originalHumanSpec('spearman',team),regalia:0,referenceSoldier:0,cape:0x7c3535,heroTrim:1,scale:1.15};if(type==='priest')return{tunic:0xe5dbc3,trim:0xc9a65d,pants:0x918265,hat:'hood',hatc:0xe5dbc3,beard:0x797064,tools:[],scale:1};return originalHumanSpec(type,team)};
const uAliases={caravan:'horseman',ram:'horseman',dragon:'simurgh',champion:'div',tyrant:'zahhak'};
unitModel=function(type,team){return originalUnitModel(uAliases[type]||type,team)};
animUnit=function(R,e,t,dt){return originalAnimUnit(R,uAliases[e.type]?{...e,type:uAliases[e.type]}:e,t,dt)};
Object.assign(AGES,{1:'Age of Fire',2:'Age of Iron',3:'Age of Heroes',4:'Age of Myth'});
Object.assign(DEF.archer,{age:2});Object.assign(DEF.simurgh,{age:3});Object.assign(DEF.barracks,{trains:['spearman'],desc:'Trains infantry.'});
Object.assign(DEF.temple,{farr:0,trains:['priest'],desc:'Train priests. Priests beside a Temple pray to generate Glory.'});
DEF.tc.cost={wood:400,gold:200};DEF.tc.time=60;
for(const t of ['archer','simurgh','barracks','temple','tc'])BASE_DEF[t]=clone(DEF[t]);
BUILDS.splice(0,BUILDS.length,'house','store','farm','barracks','temple','range','stable','blacksmith','market','wall','tower','nest','wonder','library','observatory');
for(const k of ['spearheads','armour','bows','veteran','champion'])TECH[k].at='blacksmith';
TECH.flame.eff='Priests generate Glory twice as fast.';TECH.flame.apply=()=>{memory.prayerMultiplier=2};
AGE_STEPS[2].requires=['temple'];AGE_STEPS[2].bonus='Unlock the Blacksmith, archers, cavalry and your first patron power.';
AGE_STEPS[3].requires=['temple','blacksmith'];AGE_STEPS[3].bonus='Unlock siege weapons, Simurgh’s Nest and advanced research.';
AGE_STEPS[4].requires=['temple','nest'];AGE_STEPS[4].bonus='Unlock dragons, demons and the strongest patron powers.';
