const PATRONS={2:[['rain','God of Rain','Farms produce 25% more food.','anahita'],['justice','God of Justice','Infantry gain 20% attack.','mithra'],['fortune','Goddess of Fortune','Gold gathering is 25% faster.','ahura']],3:[['messages','God of Messages','Reveal enemy strongholds.','ahura'],['wind','God of Wind','Cavalry move 25% faster.','mithra'],['healing','God of Healing','All units recover slowly outside combat.','anahita']],4:[['simurgh','The Simurgh','A Simurgh joins your army.','anahita'],['victory','God of Victory','All soldiers gain 25% attack.','mithra'],['water','Goddess of Water','Farms produce another 40% more food.','anahita']]};
function applyPatron(id){if(id==='rain')RATE.farm*=1.25;if(id==='justice')DEF.spearman.atk*=1.2;if(id==='fortune')RATE.mine*=1.25;if(id==='wind')DEF.horseman.spd*=1.25;if(id==='water')RATE.farm*=1.4;if(id==='victory')for(const t of ['spearman','archer','horseman','ram'])DEF[t].atk*=1.25;if(id==='healing')memory.healing=true;if(id==='messages'){reveals.push({x:64,y:14,r:22,until:now+3600})}}
const originalAgeRequirement=ageRequirement;
ageRequirement=function(){if(age>=currentLevel().maxAge)return 'This memory ends at '+AGES[currentLevel().maxAge]+'.';return originalAgeRequirement()};
doAgeUp=function(){if(age>=currentLevel().maxAge||age>=4)return;age++;memory.pendingPatron=age;cmdSig='';sfx('fanfare');choosePatron()};
function choosePatron(){const a=memory.pendingPatron;const options=PATRONS[a].map(([id,name,desc,power])=>({t:name+' — '+desc,f:()=>{applyPatron(id);memory.patrons.push(id);powers.push({k:power,used:false});if(id==='simurgh')spawnAlly('simurgh');memory.pendingPatron=0;closeModal();refreshPowers();saveMemory(false)}}));showMemoryCard('Choose your patron',AGES[a],'<p>'+esc(AGE_STEPS[a].bonus)+'</p>',options);if(a!==2)return;$('#modal').classList.add('patron-modal');const art=$('#story-visual'),img=$('#story-art');art.hidden=false;img.hidden=false;img.src='assets/age-of-iron-forge.png';img.alt='An ancient mountain forge at dawn, with a blacksmith working iron beside a fire temple';$('#story-caption').hidden=false;$('#story-caption').textContent='The first forge is lit. Choose the blessing that will guide this age.';$('#m-text').innerHTML='<p>Iron is ready to work. Choose one lasting blessing for your settlement.</p>';$('#m-acts').querySelectorAll('button').forEach((button,i)=>{const [,name,desc]=PATRONS[a][i];button.className='patron-choice';button.innerHTML='<span class="patron-number">0'+(i+1)+'</span><span class="patron-copy"><strong>'+esc(name)+'</strong><small>'+esc(desc)+'</small></span><span class="patron-arrow" aria-hidden="true">›</span>'})}
function spawnAlly(type,n=1){const b=ents.find(e=>e.team===0&&e.kind==='bld'&&alive(e));for(let i=0;i<n;i++){const p=b?spawnSpot(b):{x:14*TILE,y:67*TILE};mkUnit(type,0,p.x+i*12,p.y)}recalcPop()}
function available(type){const id=currentLevel().id;if(id===1)return ['villager','spearman','house','store','farm','barracks','tower','wall'].includes(type);if(id===2&&['market','range','nest','wonder','observatory','library'].includes(type))return false;if(id===3&&['wonder','observatory'].includes(type))return false;if(type==='library'&&id===3&&!memory.writing)return false;return age>=(DEF[type]?.age||1)}

// All opening, mid-mission and ending prose uses the new narrator frame.
function showMemoryCard(title,eyebrow,text,actions){paused=true;$('#modal').hidden=false;cancelAnimationFrame(sceneAnim);menuOpen=false;$('#modal').classList.remove('patron-modal');$('#modal').classList.add('memory-modal');$('#story-visual').hidden=true;$('#m-eb').textContent=eyebrow;$('#m-title').textContent=title;$('#m-text').innerHTML=text;$('#m-acts').replaceChildren();for(const a of actions||[{t:'Continue',f:closeModal}]){const b=document.createElement('button');b.className='big';b.textContent=a.t;b.onclick=a.f;$('#m-acts').append(b)}}
function memoryIntro(){const l=currentLevel();showMemoryCard(l.title,l.act+' · Memory '+l.id+' of 62','<p class="narrator">Tus, about the year 1000 · Ariel speaks to Ferdowsi</p><blockquote>“I was there. Let me tell you.”</blockquote>'+(l.id===1?'<p>Kayumars led our mountain settlement. His son, Prince Siamak, commanded its defenders; I was an orphan who helped build the refuge. Scouts had seen a Black Demon beyond the northern pass. We had time to prepare, but we knew an attack would come.</p><p>Build a training ground, grow the village and raise its defences. When the scout returns, you will lead Siamak to the pass.</p>':l.id===2?'<p>After Siamak fell, Hushang sought a way to strengthen our people. Fire came first. Iron would follow. I stayed to help his settlement learn both crafts.</p><p>Build a Fire Temple, gather gold, advance at the Town Center to the Age of Iron, then build a Blacksmith workshop with a villager.</p>':'<p>I carried the Glory through another generation. The Whisperer changed his face, but not his purpose. I could help the living; I could not undo their fate.</p>')+'<p>'+esc(l.economy)+'</p><p><b>Your mission:</b> '+esc(l.mission)+'</p><p class="ctl">Maximum: '+AGES[l.maxAge]+'. Ariel and the Whisperer are original connecting characters in this adaptation.</p>',[{t:'Begin memory',f:()=>{closeModal();beginStage()}},{t:'Campaign',f:openCampaign}])}
function openCampaign(){paused=true;$('#modal').hidden=true;cancelAnimationFrame(sceneAnim);$('#campaign').hidden=false;renderCampaign(campaign.current);}
function renderCampaign(selected){const l=CAMPAIGN_LEVELS[selected-1];$('#campaign-list').innerHTML=[...new Set(CAMPAIGN_LEVELS.map(x=>x.act))].map(act=>'<h3>'+esc(act)+'</h3>'+CAMPAIGN_LEVELS.filter(x=>x.act===act).map(x=>'<button class="memory-entry '+(x.id===selected?'selected':'')+'" data-level="'+x.id+'"><span>'+String(x.id).padStart(2,'0')+'</span><b>'+esc(x.title)+'</b><small>'+(campaign.completed.includes(x.id)?'Completed':canStart(x.id)?'Available':'Locked')+'</small></button>').join('')).join('');$('#campaign-detail').innerHTML='<p class="ey">'+esc(l.act)+' · Memory '+l.id+'</p><h2>'+esc(l.title)+'</h2><p>'+esc(l.economy)+'</p><h3>The mission</h3><p>'+esc(l.mission)+'</p><p class="ctl">Age limit: '+AGES[l.maxAge]+' · '+PLANS[l.id].filter(s=>s.kind!=='event').length+' objectives</p><button class="big" id="start-memory" '+(!canStart(l.id)?'disabled':'')+'>'+(campaign.completed.includes(l.id)?'Replay memory':'Begin memory')+'</button>'+(!canStart(l.id)?'<p class="ctl">Complete memory '+(l.id-1)+' to unlock this story.</p>':'');$('#start-memory').onclick=()=>startMemory(l.id);$('#campaign-progress').textContent=campaign.completed.length+' / 62 memories completed';$('#resume-memory').hidden=!readSave();$('#return-memory').hidden=!campaignActive||gameOver;$('#campaign-list').querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>renderCampaign(+b.dataset.level));}
// Development switch: every memory can be started without finishing the previous one.
// Set to false before a public release to restore normal story progression.
const DEV_UNLOCK_ALL=true;
function canStart(id){return DEV_UNLOCK_ALL||id===1||campaign.completed.includes(id)||campaign.completed.includes(id-1)}
let renderedLandscape=1,staticWorld=[],landscapeBusy=false;
const originalBuildWorld3D=buildWorld3D;
buildWorld3D=function(){const before=new Set(scene.children);try{originalBuildWorld3D();renderedLandscape=LANDSCAPE_SEED}finally{staticWorld=scene.children.filter(child=>!before.has(child))}};
function clearLandscape3D(){const seen=new Set();for(const child of staticWorld)disposeVisual(child,seen);staticWorld=[];CHUNKS.length=0;scatIM.length=0;scatByTile.clear();treeIM={};rallyObj=null;scene.userData.sky=null;renderedLandscape=0}
function setRiverForMemory(id){if(id===1){RIV.splice(0,RIV.length,[24,-3],[27,12],[35,28],[50,39],[66,43.5],[83,47]);return}const rand=mulberry32(8303+id*733),bend=()=>rand()*8-4;RIV.splice(0,RIV.length,[24+bend(),-3],[27+bend(),12],[31,20],[35+bend(),28],[43.25,34.05],[50+bend(),39],[59.6,41.7],[66+bend(),43.5],[74.5,45.25],[83,47+bend()])}
async function prepareLandscape(id){if(renderedLandscape===id)return;$('#loading').hidden=false;$('#lmsg').textContent='Shaping the landscape for '+CAMPAIGN_LEVELS[id-1].title+'…';$('#lbar').style.width='0%';clearWorld3D();clearLandscape3D();LANDSCAPE_SEED=id;setRiverForMemory(id);originalMiniMap=null;try{await genWorldData(p=>{$('#lbar').style.width=(p*100)+'%'});buildWorld3D()}catch(err){clearLandscape3D();throw err}$('#loading').hidden=true}
async function startMemory(id){if(!canStart(id)||landscapeBusy)return;landscapeBusy=true;$('#campaign').hidden=true;campaign.current=id;saveProgress();memory={id,stage:0,stageAt:0,started:false,targets:[],patrons:[],wave:0,kills:0,deliveries:0,duels:0,blessing:0,prayerMultiplier:1};campaignActive=true;try{await prepareLandscape(id);setupWorld();memoryIntro();saveMemory(false)}catch(err){console.error(err);$('#loading').hidden=true;showMemoryCard('Map could not load','Please retry','<p>The landscape could not be prepared. Try beginning this memory again.</p>',[{t:'Campaign',f:openCampaign}])}finally{landscapeBusy=false}}

// Every memory has a reproducible terrain signature. The nine acts set the broad
// biome, while the memory number changes its tint, tree cover and landform layout.
const LANDSCAPE_LOOKS=[
  {tone:[.96,1.02,1.08],trees:.78,forms:['ridge','snowcrest']},
  {tone:[1.08,.99,.85],trees:.52,forms:['mesa','stonefield']},
  {tone:[1.11,.91,.78],trees:.37,forms:['mesa','ridge']},
  {tone:[.87,1.08,.88],trees:.9,forms:['copse','ridge']},
  {tone:[.97,.92,.86],trees:.49,forms:['stonefield','mesa']},
  {tone:[.9,.98,1.12],trees:.65,forms:['snowcrest','ridge']},
  {tone:[.92,1.07,1.01],trees:.86,forms:['copse','stonefield']},
  {tone:[.87,.91,1.01],trees:.56,forms:['ridge','stonefield']},
  {tone:[1.03,1.05,.88],trees:.72,forms:['copse','mesa']}
];
const ACT_NAMES=[...new Set(CAMPAIGN_LEVELS.map(l=>l.act))];
const LANDSCAPE_TYPES=new Set(['ridge','mesa','copse','stonefield','snowcrest']);
let originalMiniMap=null;
function landscapeLook(id){return LANDSCAPE_LOOKS[Math.max(0,ACT_NAMES.indexOf(CAMPAIGN_LEVELS[id-1].act))]}
function applyLandscape(id){
  const look=landscapeLook(id),tone=look.tone,variation=.94+hash2(id,47)*.12;
  for(const mesh of scene.children){const geo=mesh.geometry,colors=geo?.attributes?.tint,positions=geo?.attributes?.position;if(!colors||!geo.attributes.splat||!positions)continue;
    for(let i=0;i<colors.count;i++){const x=positions.getX(i),z=positions.getZ(i),ix=clamp(Math.round((x-HOFF)*HR),0,HN-1),iz=clamp(Math.round((z-HOFF)*HR),0,HN-1),k=(iz*HN+ix)*3;const local=.97+.03*Math.sin(x*.23+id*1.7)*Math.cos(z*.19-id*.8);colors.setXYZ(i,TINT[k]*tone[0]*variation*local,TINT[k+1]*tone[1]*variation*local,TINT[k+2]*tone[2]*variation*local)}colors.needsUpdate=true;
  }
  const ctx=miniBase.getContext('2d');if(!originalMiniMap)originalMiniMap=new Uint8ClampedArray(ctx.getImageData(0,0,160,160).data);const im=ctx.createImageData(160,160);for(let i=0;i<im.data.length;i+=4){im.data[i]=Math.min(255,originalMiniMap[i]*tone[0]*variation);im.data[i+1]=Math.min(255,originalMiniMap[i+1]*tone[1]*variation);im.data[i+2]=Math.min(255,originalMiniMap[i+2]*tone[2]*variation);im.data[i+3]=255}ctx.putImageData(im,0,0);
}
function addLandscapeForms(id){if(id===1)return;const look=landscapeLook(id),rand=mulberry32(9191+id*883),count=7+id%5;let placed=0;
  for(let attempt=0;attempt<450&&placed<count;attempt++){const x=5+Math.floor(rand()*68),y=8+Math.floor(rand()*61),cx=x+1.5,cy=y+1.5;if(Math.hypot(cx-14,cy-65)<11||targetSites.some(p=>Math.hypot(cx-p[0],cy-p[1])<7)||MAP_PATHS.some(p=>segD(cx,cy,...p)<3.6))continue;if(!fits(x,y,3,3))continue;const type=look.forms[Math.floor(rand()*look.forms.length)];mkBld(type,2,x,y,true);placed++}
  memory.landscapeForms=placed;
}

setupWorld=function(){resetStats();clearWorld3D();ents=[];byId.clear();nextId=1;projs=[];fxs=[];pings=[];reveals=[];blocked.set(tblk);occ.fill(0);vis.fill(0);expl.fill(0);res={food:250,wood:250,gold:150,farr:0};age=1;now=0;gameOver=false;flags={};powers=[];sel=[];placing=null;wallStart=null;targeting=null;blessing=0;blessingMode=false;aiT=trigT=fogT=0;palaceDown=false;zahhakSpawned=false;const l=currentLevel();applyLandscape(l.id);
  if(l.id===1){memory.settlementRevision=3;res={food:600,wood:650,gold:0,farr:0};DEF.tower.cost={wood:120};DEF.tower.name='Mountain Watchtower';DEF.barracks.trains=['spearman'];DEF.barracks.name='Training Ground';DEF.wall.cost={wood:25};DEF.gate.cost={wood:45};DEF.farm.age=1;DEF.spearman.name='Stone Defender';DEF.spearman.cost={food:60};DEF.spearman.atk=7;DEF.serpent.atk=5;DEF.champion.name='The Black Demon';DEF.villager.desc='Builds the settlement, gathers wood and food, and farms. Train more villagers at the cave.';DEF.companion.name='Prince Siamak';DEF.companion.desc='Kayumars’s son. Lead him to the marked pass when the Black Demon is sighted.';}
  if(l.id>1){const growth=1+(l.id-2)*.0075;for(const t of ['serpent','bowman','champion','tyrant']){DEF[t].hp=Math.round(DEF[t].hp*growth);DEF[t].atk*=growth;}}
  DEF.wonder.name=({4:'Jamshid’s Palace',22:'Siavash’s City',44:'Great Iron Wall',54:'Great Palace Arch',59:'Royal Palace'})[l.id]||'Wonder';
  if(l.id===1)for(const [x,y] of [[6,54],[0,46],[16,46],[32,38],[48,30],[64,22],[0,30],[16,22]])mkBld('mountain',2,x,y,true);
  const home=mkBld(l.id===1?'cave':'tc',0,12,62,true);for(let i=0;i<(l.id===1?5:6);i++)mkUnit('villager',0,(12+i*.9)*TILE,67*TILE);mkUnit('ariel',0,17*TILE,66.5*TILE);for(let i=0;i<(l.id===1?6:3);i++)mkUnit('spearman',0,(12+i)*TILE,69*TILE);
  if(l.id===1){mkBld('house',0,7,65,true);mkBld('house',0,9,69,true);mkBld('store',0,18,63,true);mkBld('farm',0,21,63,true);}
  if(l.id===1)mkUnit('companion',0,18*TILE,67*TILE);else if(l.id===6){mkUnit('kaveh',0,18*TILE,67*TILE);mkUnit('fereydun',0,19*TILE,67*TILE)}else if(l.id>6){DEF.companion.name=l.id<=8?'Manuchehr':l.id<=11?'Zal':l.id<=35?'Rostam':l.id<=39?'Esfandiyar':'Royal champion';mkUnit('companion',0,18*TILE,67*TILE)}
  for(const p of [[20,67],[21,68],[22,67],[20,69],[22,69],[21,70],[9,58],[10,58],[8,57],[37,61],[38,62],[36,62],[37,63]])placeFree('bush',2,...p);
  if(l.id!==1)for(const p of [[23,57],[7,71],[40,52],[49,66],[29,74],[50,24],[70,32],[33,44]])placeFree('mine',2,...p);
  for(const p of [[8,65],[20,74],[9,72]]){const r=placeFree('bush',2,...p);if(r)r.amt=1000}
  const post=placeFree('tradepost',2,38,60,true);if(post)memory.tradepost=post.id;
  addLandscapeForms(l.id);
  TREES.forEach((t,k)=>{const i=t.ty*MW+t.tx;if(occ[i]||blocked[i]||(l.id>1&&hash2(t.tx+l.id*13,t.ty+l.id*31)>landscapeLook(l.id).trees)){hideTree(k);return}const e=mkRes('tree',t.tx,t.ty);e.ti=k});
  OBJ=[];cam.z0=l.id===1?29:Math.min(innerWidth,innerHeight)<520?14:22;centerOn(home.x,home.y);recalcPop();updateFog();portCache.clear();selSig=cmdSig=objSig='';refreshPowers();refreshSel();refreshObj();$('#obj').classList.remove('min');$('#objh span').textContent='hide';};

const targetSites=[[36,61],[48,58],[48,44],[60,38],[46,28],[58,21],[65,12]];
function missionPoint(index=0){const p=targetSites[Math.min(6,index)];const f=nearFree(p[0],p[1]);return f?{x:f.x*TILE+16,y:f.y*TILE+16}:{x:p[0]*TILE,y:p[1]*TILE}}
function stageTarget(type,team,index){const p=targetSites[Math.min(6,index)];for(const e of ents)if(e.kind==='res'&&Math.hypot(e.tx-p[0],e.ty-p[1])<6){e.dead=true;stampE(e,false);resGone(e)}buildGrid();const d=DEF[type];return d.kind==='bld'?placeFree(type,team,p[0],p[1],true):mkUnit(type,team,missionPoint(index).x,missionPoint(index).y)}
function beginStage(){if(!memory||gameOver)return;const s=PLANS[memory.id][memory.stage];if(!s){finishMemory();return}memory.started=true;memory.stageAt=now;memory.targets=[];memory.wave=0;memory.deliveries=0;memory.duels=0;memory.goal=0;memory.marker=null;memory.actionReady=false;memory.drainTick=0;saveMemory(false);
  if(s.kind==='siamak'){let prince=ents.find(e=>e.type==='companion'&&e.team===0&&alive(e));if(!prince){const home=ents.find(e=>e.type==='cave'&&e.team===0);const p=home?spawnSpot(home):{x:18*TILE,y:67*TILE};prince=mkUnit('companion',0,p.x,p.y)}memory.siamakId=prince.id;memory.duelStarted=false;memory.duelResolved=false;memory.marker=missionPoint(0);updateFog();refreshMissionHUD();saveMemory(false);showMemoryCard('The scout returns','Kayumars · the northern pass','<p>The Black Demon has crossed the northern ridge. Prince Siamak, Kayumars’s son and captain of your defenders, goes to meet it before it reaches the village.</p><p><b>What to do:</b> Select Prince Siamak and send him to the gold mission marker at the pass. The village remains yours to defend.</p>',[{t:'Find Prince Siamak',f:()=>{closeModal();setSel([prince.id]);centerOn(prince.x,prince.y)}}]);return}
  if(s.kind==='event'){if(['The death of Siamak','The death of Iraj','The death of Siavash','Nowzar falls','The last king','The cost of obedience'].includes(s.text)){for(const e of ents)if(e.type==='companion'&&e.team===0){e.dead=true;e.fallen=false}}saveMemory(false);showMemoryCard(s.text,'Ariel remembers','<p>'+esc(s.body)+'</p>',[{t:'Continue the memory',f:()=>{closeModal();advanceStage()}}]);return}
  if(s.kind==='fight'||s.kind==='race'){for(let i=0;i<(s.n||1);i++){const e=stageTarget(s.type||'stronghold',1,Math.min(6,1+i+memory.stage%3));if(e){e.guard=1;e.hx=e.x;e.hy=e.y;memory.targets.push(e.id);for(let j=0;j<3;j++)mkUnit('serpent',1,e.x+(j-1)*24,e.y+100,{guard:1,hx:e.x,hy:e.y+100})}}}
  if(s.kind==='capture'){for(let i=0;i<s.n;i++){const e=stageTarget('champion',1,i%7);e.hp=300;e.captureChief=true;e.guard=1;e.hx=e.x;e.hy=e.y;memory.targets.push(e.id)}}
  if(['reach','escort','tribute'].includes(s.kind)){memory.marker=missionPoint(memory.stage%3);if(s.kind==='escort'){for(let i=0;i<s.count;i++){const e=mkUnit('villager',2,memory.marker.x+i*18,memory.marker.y);e.escort=true;memory.targets.push(e.id)}memory.escorting=false}}
  if(s.kind==='rescue'){memory.rescueAt=now+25;memory.detection=0}
  if(s.kind==='blind')memory.blind=true;
  if(s.kind==='famine')res.food=0;
  if(s.kind==='duel')spawnDuel();
  if(s.kind==='side'){showMemoryCard('Rostam or Esfandiyar?','A divided loyalty','<p>Ariel may choose whom to aid, but cannot change Esfandiyar’s fate.</p>',[{t:'Aid Rostam',f:()=>{memory.side='Rostam';closeModal();advanceStage()}},{t:'Aid Esfandiyar',f:()=>{memory.side='Esfandiyar';closeModal();advanceStage()}}]);return}
  if(memory.targets.length){const e=byId.get(memory.targets[0]);if(e)memory.marker={x:e.x,y:e.y}}
  OBJ=PLANS[memory.id].filter(x=>x.kind!=='event').map((x,i)=>({id:'memory-'+i,text:x.text,done:PLANS[memory.id].indexOf(x)<memory.stage,hidden:PLANS[memory.id].indexOf(x)>memory.stage}));refreshObj();saveMemory(false);}
function advanceStage(){memory.stage++;memory.started=false;beginStage()}
function showSiamakAftermath(){showMemoryCard('Siamak falls at the pass','What happened · what comes next','<p>You sent Prince Siamak to hold the northern pass. He met the Black Demon there and fell in the fight. The demon withdrew, but its army is coming for Kayumars’s settlement.</p><p>Sorush now calls Ariel to guard the Glory of the Kings. Ariel cannot undo Siamak’s death; he can help protect the people Siamak fought for.</p><p><b>Next:</b> Return to your village. Train defenders, repair your buildings and survive three small demon attacks.</p>',[{t:'Return and defend the village',f:()=>{closeModal();advanceStage();const home=ents.find(e=>e.type==='cave'&&e.team===0&&alive(e));if(home)centerOn(home.x,home.y)}}])}
function spawnDuel(){const s=PLANS[memory.id][memory.stage];const e=stageTarget('champion',1,0);e.hp=200+memory.duels*20;e.duelist=true;e.guard=1;e.hx=e.x;e.hy=e.y;memory.targets=[e.id];memory.marker={x:e.x,y:e.y};}
function finishMemory(){gameOver=true;paused=true;if(!campaign.completed.includes(memory.id))campaign.completed.push(memory.id);campaign.current=Math.min(62,memory.id+1);saveProgress();try{localStorage.removeItem(RUN_KEY)}catch(_){}const last=memory.id===62;showMemoryCard(last?'The story survives':'A memory preserved','Tus · Ariel and Ferdowsi',last?'<p>Ariel finishes his account. Sorush has carried him across the centuries to this meeting. His immortality has ended, but Ferdowsi promises that the stories will live in his poem. The Glory the Whisperer sought survives in memory.</p>':'<p>'+esc(currentLevel().mission)+'</p><p>Ferdowsi sets down this memory. Ariel turns to the next generation.</p>',[{t:last?'Return to the chronicle':'Next memory',f:last?openCampaign:()=>startMemory(memory.id+1)},{t:'Campaign',f:openCampaign}]);}
defeat=function(){if(gameOver)return;gameOver=true;paused=true;showMemoryCard('The memory is unfinished','Retry this mission','<p>The refuge has fallen or the people needed for this mission have been lost. The scripted tragedies are part of the story; this defeat can be retried.</p>',[{t:'Retry memory',f:()=>startMemory(memory.id)},{t:'Campaign',f:openCampaign}])};
restart=()=>startMemory(memory?.id||campaign.current);
onPalaceDown=()=>{};onZahhakDown=()=>{};

function launchMemoryWave(n){const home=ents.find(e=>e.team===0&&['tc','cave'].includes(e.type)&&alive(e));if(!home)return;const p=missionPoint(n%2);const count=memory.id===1?[3,5,7][n]:Math.min(20,4+n+Math.floor((memory.id-2)/6)+(campaign.difficulty==='hard'?3:0));for(let i=0;i<count;i++){const e=mkUnit(memory.id===1?'serpent':i%4===3?'bowman':'serpent',1,p.x+i*20,p.y);e.memoryWave=true;if(memory.id===1){e.hp=60+n*15;}orderMove(e,home.x,home.y,true)}msg('Enemy wave '+(n+1)+' approaches.','warn')}
aiTick=function(){if(!campaignActive||!memory||gameOver)return;for(const e of ents)if(e.fallen&&now>=e.respawnAt){const home=ents.find(b=>b.team===0&&['tc','cave'].includes(b.type)&&alive(b));if(home){const p=spawnSpot(home);Object.assign(e,{x:p.x,y:p.y,fallen:false,hp:DEF[e.type].hp,state:'idle'});msg(DEF[e.type].name+' returns to the refuge.','good')}}};
triggers=function(){if(!campaignActive||!memory||gameOver||!memory.started||paused)return;const s=PLANS[memory.id][memory.stage];if(!s||s.kind==='event'||s.kind==='side')return;const elapsed=now-memory.stageAt,has=t=>ents.some(e=>e.type===t&&e.team===0&&e.done&&alive(e));const people=ents.filter(e=>e.type==='villager'&&e.team===0&&alive(e));const ariel=ents.find(e=>e.type==='ariel'&&alive(e));const army=ents.filter(e=>e.team===0&&alive(e)&&['inf','arc','cav','siege'].includes(DEF[e.type].cls));let done=false;
  if(s.kind==='siamak'){const prince=byId.get(memory.siamakId);if(!memory.duelStarted&&prince&&memory.marker&&Math.hypot(prince.x-memory.marker.x,prince.y-memory.marker.y)<2*TILE){memory.duelStarted=true;memory.duelAt=now;const demon=mkUnit('champion',1,memory.marker.x+2*TILE,memory.marker.y,{guard:1,hx:memory.marker.x+2*TILE,hy:memory.marker.y});demon.hp=3000;memory.duelEnemy=demon.id;orderAttack(prince,demon);orderAttack(demon,prince);centerOn(memory.marker.x,memory.marker.y);cam.z0=14;msg('At the pass: Siamak faces the Black Demon.','warn');refreshMissionHUD();saveMemory(false)}else if(memory.duelStarted&&!memory.duelResolved&&now-memory.duelAt>=8){memory.duelResolved=true;if(prince){prince.dead=true;prince.fallen=false;sel=sel.filter(id=>id!==prince.id);fxs.push({t:'hit',x:prince.x,y:prince.y,life:.8,max:.8})}const demon=byId.get(memory.duelEnemy);if(demon)demon.dead=true;sfx('death',memory.marker.x,memory.marker.y);saveMemory(false);showSiamakAftermath();return}refreshMissionHUD();return}
  if(s.kind==='build')done=has(s.type);
  if(s.kind==='prepare')done=people.length>=8&&army.filter(e=>e.type!=='companion').length>=8&&has('tower');
  if(s.kind==='stock')memory.actionReady=afford(s.cost);
  if(['fight','capture','race'].includes(s.kind)){done=memory.targets.length>0&&memory.targets.every(id=>{const e=byId.get(id);return !alive(e)||e.team===0});if(s.kind==='capture'&&done)memory.writing=true;if(s.kind==='race'&&elapsed>s.seconds&&!done){defeat();return}}
  if(s.kind==='reach'&&ariel&&memory.marker)done=Math.hypot(ariel.x-memory.marker.x,ariel.y-memory.marker.y)<3*TILE;
  if(s.kind==='escort'){if(!memory.escorting&&ariel&&Math.hypot(ariel.x-memory.marker.x,ariel.y-memory.marker.y)<4*TILE){memory.escorting=true;memory.marker={x:14*TILE,y:67*TILE};for(const id of memory.targets){const e=byId.get(id);if(e)e.team=0}msg('The refugees join you. Bring them to your starting refuge.','good')}if(memory.escorting){if(memory.targets.some(id=>!alive(byId.get(id)))){defeat();return}done=memory.targets.every(id=>{const e=byId.get(id);return Math.hypot(e.x-14*TILE,e.y-67*TILE)<6*TILE})}}
  if(['hold','tax','famine','succession'].includes(s.kind)){const waves=s.waves||3;if(memory.wave<waves&&elapsed>(memory.id===1?60+memory.wave*80:20+memory.wave*(s.seconds-30)/waves)){launchMemoryWave(memory.wave++);}done=elapsed>=s.seconds&&(!s.n||people.length>=s.n);if(memory.id===1&&s.kind==='hold')done=memory.wave>=3&&people.length>0&&!ents.some(e=>e.memoryWave&&alive(e));if(['tax','famine'].includes(s.kind)){const tick=Math.floor(elapsed/15);if(tick>(memory.drainTick||0)){memory.drainTick=tick;const key=s.kind==='famine'?'food':'gold';res[key]=Math.max(0,res[key]-25);if(s.kind==='famine'&&res.food===0)for(const p of people){p.hp-=3;if(p.hp<=0)kill(p,null)}}}if(s.kind==='succession'){const reign=Math.min(5,Math.floor(elapsed/120)+1);if(reign!==memory.reign){memory.reign=reign;msg('A new ruler: '+['food tribute','gold tribute','military levy','wood tribute','Glory tribute'][reign-1]+'.','warn');const key=['food','gold','food','wood','farr'][reign-1];res[key]=Math.max(0,res[key]-100)}}}
  if(['blind','ambush'].includes(s.kind))done=army.length>=s.n;
  if(s.kind==='rescue'){if(now>=memory.rescueAt){spawnAlly('villager');memory.rescueAt=now+25;msg('The cooks have saved another youth.','good')}memory.detection=ents.some(e=>e.team===1&&alive(e)&&Math.hypot(e.x-14*TILE,e.y-64*TILE)<8*TILE)?memory.detection+.5:Math.max(0,memory.detection-.25);if(elapsed>60&&memory.wave<3&&elapsed>60+memory.wave*140){launchMemoryWave(memory.wave++);}if(memory.detection>=30){defeat();return}done=people.length>=s.n;}
  if(s.kind==='tribute')done=memory.deliveries>=s.n;
  if(s.kind==='duel'&&memory.targets.every(id=>!alive(byId.get(id)))){memory.duels++;if(memory.duels>=s.n)done=true;else spawnDuel()}
  if(s.kind==='court')done=memory.goal>=s.n;
  if(memory.id===25){const winter=Math.floor(now/120)%2===1;if(winter!==memory.winter){memory.winter=winter;RATE.bush*=winter?.6:1/.6;RATE.farm*=winter?.6:1/.6;msg(winter?'Winter: food gathering slows.':'Spring: food gathering recovers.')}}
  if(memory.id===60&&ariel)ariel.hp=Math.max(40,ariel.hp-.35);
  if(!people.length&&!ents.some(e=>e.team===0&&['tc','cave'].includes(e.type)&&alive(e))){defeat();return}
  if(done){msg('Objective complete: '+s.text,'good');res.farr+=memory.id>1?15:0;advanceStage()}else refreshMissionHUD();};

const originalKill=kill, originalUpdBld=updBld, originalUpdUnit=updUnit, originalCommand=commandInner;
kill=function(e,by){if(e.captureChief&&by?.team===0){e.team=0;e.hp=DEF[e.type].hp;e.captureChief=false;e.state='idle';e.target=0;spawnAlly('villager');res.farr+=10;msg('A demon chief is captured alive and joins the workers.','good');return}originalKill(e,by);if(e.type==='cave'&&e.team===0&&e.dead)defeat();};
updBld=function(b,dt){originalUpdBld(b,dt*(b.id===blessing?1.2:1))};
updUnit=function(e,dt){if(e.type==='priest'){const t=ents.find(b=>b.type==='temple'&&b.team===0&&b.done&&alive(b)&&Math.hypot(b.x-e.x,b.y-e.y)<5*TILE);if(t&&e.state!=='move')res.farr+=.6*dt*(memory?.prayerMultiplier||1)*(t.id===blessing?1.2:1)}if(memory?.healing&&e.team===0&&e.state!=='attack')e.hp=Math.min(DEF[e.type].hp,e.hp+dt*.5);originalUpdUnit(e,dt*(e.type==='villager'&&e.target===blessing&&e.anim==='work'?1.2:1));if(e.type==='caravan'&&e.team===0&&e.state==='idle'){const post=byId.get(memory.tradepost),market=ents.find(b=>b.type==='market'&&b.team===0&&b.done&&alive(b));if(post&&market){const dest=e.tradeReturn?market:post;if(Math.hypot(e.x-dest.x,e.y-dest.y)<5*TILE){if(e.tradeReturn){res.gold+=40;e.tradeReturn=false}else e.tradeReturn=true}const next=e.tradeReturn?market:post;orderMove(e,next.x,next.y)}}};
commandInner=function(x,y,t,S){if(blessingMode){if(t?.kind==='bld'&&t.team===0){blessing=t.id;memory.blessing=blessing;blessingMode=false;msg(DEF[t.type].name+' blessed: works 20% faster.','good');refreshMissionHUD()}else{blessingMode=false;msg('Movement order.');refreshMissionHUD();originalCommand(x,y,t,S)}return}originalCommand(x,y,t,S)};
const originalLeftClick=leftClick;
leftClick=function(x,y,shift){if(blessingMode){const e=pickEnt(x,y);if(e?.kind==='bld'&&e.team===0){commandInner(0,0,e,[]);return}blessingMode=false;msg('Blessing selection cancelled.');refreshMissionHUD();}originalLeftClick(x,y,shift)};
const originalCmdList=cmdList, originalCanDo=canDo, originalDoAct=doAct;
cmdList=function(){return originalCmdList().filter(c=>{const [a,t]=c.act.split(':');if(a==='build'||a==='train')return available(t);if(c.act==='ageup')return age<currentLevel().maxAge;return true})};
canDo=function(act){const [a,t]=act.split(':');if((a==='build'||a==='train')&&!available(t))return false;return originalCanDo(act)};
doAct=function(act){if(!canDo(act)){msg('This action is not available in the current memory or age.','warn');return}originalDoAct(act)};
const originalFog=updateFog;
updateFog=function(){if(!memory?.blind){originalFog();return}const saved={};for(const t in DEF)if(DEF[t].los){saved[t]=DEF[t].los;DEF[t].los=2}originalFog();for(const t in saved)DEF[t].los=saved[t]};

function refreshMissionHUD(){if(!memory||!campaignActive)return;const l=currentLevel(),s=PLANS[memory.id][memory.stage];$('#memory-title').textContent=String(l.id).padStart(2,'0')+' · '+l.title;$('#memory-age').textContent='Maximum '+AGES[l.maxAge];const elapsed=now-memory.stageAt;let extra='';if(s?.seconds)extra=' · '+Math.max(0,Math.ceil(s.seconds-elapsed))+'s remaining';if(s?.kind==='prepare')extra=' · '+ents.filter(e=>e.type==='villager'&&e.team===0&&alive(e)).length+'/8 villagers · '+ents.filter(e=>e.team===0&&alive(e)&&e.type!=='companion'&&['inf','arc','cav','siege'].includes(DEF[e.type].cls)).length+'/8 defenders · '+(ents.some(e=>e.type==='tower'&&e.team===0&&e.done&&alive(e))?'watchtower ready':'build a watchtower');if(memory.id===1&&s?.kind==='hold')extra=' · '+memory.wave+'/3 waves · '+ents.filter(e=>e.memoryWave&&alive(e)).length+' enemies remaining'+(memory.wave<3?' · next wave in '+Math.max(0,Math.ceil(60+memory.wave*80-elapsed))+'s':'');if(s?.kind==='rescue')extra=' · '+ents.filter(e=>e.type==='villager'&&e.team===0&&alive(e)).length+'/40 people · detection '+Math.floor(memory.detection||0)+'/30';if(s?.kind==='tribute')extra=' · '+memory.deliveries+'/'+s.n+' delivered';if(s?.kind==='duel')extra=' · '+memory.duels+'/'+s.n+' duels';$('#memory-objective').textContent=(s?.text||'Memory complete')+extra;const b=byId.get(blessing);$('#blessing-state').textContent=b&&alive(b)?DEF[b.type].name+' · +20%':'No building blessed';const act=$('#mission-action');act.hidden=!s||!['stock','tribute','puzzle','court'].includes(s.kind);act.disabled=false;if(s?.kind==='stock'){act.textContent='Commit '+costLong(s.cost);act.disabled=!afford(s.cost)}if(s?.kind==='tribute'){act.textContent='Send gift caravan · 120 gold, 40 wood';act.disabled=!afford(s.cost)||!ents.some(e=>e.type==='market'&&e.done&&e.team===0&&alive(e))}if(s?.kind==='puzzle')act.textContent='Meet the wise minister';if(s?.kind==='court'){act.textContent='Hold audience · 100 food, 80 gold ('+memory.goal+'/'+s.n+')';act.disabled=!afford({food:100,gold:80})}}
function missionAction(){if(paused||gameOver)return;const s=PLANS[memory.id][memory.stage];if(s.kind==='stock'&&afford(s.cost)){pay(s.cost);advanceStage()}else if(s.kind==='tribute'&&afford(s.cost)){const market=ents.find(e=>e.type==='market'&&e.done&&e.team===0&&alive(e));if(!market)return;pay(s.cost);const p=spawnSpot(market);const e=mkUnit('caravan',0,p.x,p.y);e.gift=true;orderMove(e,memory.marker.x,memory.marker.y);memory.gifts=memory.gifts||[];memory.gifts.push(e.id)}else if(s.kind==='puzzle'){showMemoryCard('The wise minister','Chess and backgammon','<p>On the chessboard, which piece must be protected for the kingdom to survive?</p>',[{t:'The king',f:()=>showMemoryCard('A game of time and chance','The minister’s reply','<p>Chess tests foresight. Backgammon adds the turn of the dice: a reminder that wisdom must also respond to chance.</p>',[{t:'Present backgammon to the court',f:()=>{closeModal();advanceStage()}}])},{t:'A pawn',f:()=>msg('The minister invites you to reconsider.')}])}else if(s.kind==='court'&&afford({food:100,gold:80})){pay({food:100,gold:80});memory.goal++;msg(memory.goal%2?'The court supports Ariel’s counsel.':'The Whisperer’s accusation is answered.','good')}refreshMissionHUD()}
const originalUpdate=update;
update=function(dt){originalUpdate(dt);if(!campaignActive||!memory||gameOver)return;for(const id of memory.gifts||[]){const e=byId.get(id);if(e&&alive(e)&&memory.marker&&Math.hypot(e.x-memory.marker.x,e.y-memory.marker.y)<5*TILE){e.gift=false;e.dead=true;memory.deliveries++;memory.gifts=memory.gifts.filter(x=>x!==id);msg('A gift caravan arrives.','good')}}if(now-(memory.lastSave||0)>45){memory.lastSave=now;saveMemory(false)}};

function readSave(){try{const s=JSON.parse(localStorage.getItem(RUN_KEY));return s&&s.version===CAMPAIGN_VERSION&&s.memory?.id>=1&&s.memory?.id<=62&&Array.isArray(s.ents)?s:null}catch(_){return null}}
function saveMemory(notify=true){if(!memory||gameOver)return false;const data={version:CAMPAIGN_VERSION,memory,ents:ents.filter(e=>!e.dead).map(e=>{const {tgt,...rest}=e;return rest}),res,age,now,nextId,blessing,powers,techs:[...techs],expl:Array.from(expl),reveals};try{localStorage.setItem(RUN_KEY,JSON.stringify(data));if(notify)msg('Memory saved at '+Math.floor(now/60)+':'+String(Math.floor(now%60)).padStart(2,'0')+' · '+Math.floor(res.food)+' food, '+Math.floor(res.wood)+' wood.','good');return true}catch(_){if(notify)msg('Could not save: browser storage is full or unavailable.','warn');return false}}
function resumeMemory(){const s=readSave();if(!s)return;if(s.memory.id===1&&s.memory.settlementRevision!==3){$('#campaign').hidden=true;showMemoryCard('A new mountain settlement','Opening mission rebuilt','<p>This saved attempt uses the old cave scenario. Begin the rebuilt mission with a settlement, five villagers, six defenders and supplies. Your campaign unlocks are kept.</p>',[{t:'Begin rebuilt mission',f:()=>startMemory(1)},{t:'Campaign',f:openCampaign}]);return;}$('#campaign').hidden=true;campaign.current=s.memory.id;memory=clone(s.memory);campaignActive=true;setupWorld();memory=clone(s.memory);clearWorld3D();ents=[];byId.clear();occ.fill(0);blocked.set(tblk);for(const t of s.techs){if(TECH[t]){TECH[t].apply();techs.add(t)}}for(const p of memory.patrons)applyPatron(p);if(memory.winter){RATE.bush*=.6;RATE.farm*=.6}ents=s.ents;byId=new Map(ents.map(e=>[e.id,e]));for(const e of ents)if(e.kind!=='unit'){stampE(e,true);if(e.type!=='tree')onPlaced(e)}nextId=s.nextId;res=s.res;age=s.age;now=s.now;blessing=s.blessing;powers=s.powers;reveals=s.reveals;expl.set(s.expl);const activeTrees=new Set(ents.filter(e=>e.type==='tree').map(e=>e.ti));TREES.forEach((t,k)=>{if(!activeTrees.has(k))hideTree(k)});OBJ=PLANS[memory.id].filter(x=>x.kind!=='event').map((x,i)=>({id:'memory-'+i,text:x.text,done:PLANS[memory.id].indexOf(x)<memory.stage,hidden:PLANS[memory.id].indexOf(x)>memory.stage}));paused=false;gameOver=false;closeModal();recalcPop();updateFog();refreshPowers();refreshObj();refreshMissionHUD();if(memory.pendingPatron)choosePatron();else if(!memory.started)memoryIntro();else if(PLANS[memory.id][memory.stage]?.kind==='side'){const st=memory.stage;memory.started=false;beginStage()}else if(PLANS[memory.id][memory.stage]?.kind==='event'){const ev=PLANS[memory.id][memory.stage];showMemoryCard(ev.text,'Ariel remembers','<p>'+esc(ev.body)+'</p>',[{t:'Continue',f:()=>{closeModal();advanceStage()}}])}}

openMenu=function(){if(!$('#modal').hidden)return;showMemoryCard('Ariel of the Shahnameh','Paused','<p>'+esc(currentLevel().title)+' · Memory '+currentLevel().id+' / 62</p><p>Progress saves automatically. Use Save memory before leaving. Select Ariel, then Bless building to move his 20% work bonus.</p>',[{t:'Resume',f:closeModal},{t:'Save memory',f:()=>saveMemory()},{t:'Campaign',f:()=>{saveMemory(false);openCampaign()}},{t:'Restart memory',f:restart}])};
const originalHUD=hudTick;
hudTick=function(){originalHUD();refreshMissionHUD();$('#age').textContent=AGES[age]+(age<currentLevel().maxAge?' ↑':' · limit');const h=$('#memory-hud');h.style.top=($('#top').getBoundingClientRect().bottom+12)+'px';$('#obj').style.top=(h.getBoundingClientRect().bottom+10)+'px';};
const originalOverlay=drawOverlay;
drawOverlay=function(){originalOverlay();if(!campaignActive||!memory?.marker||$('#campaign').hidden===false)return;const p=toScreen(memory.marker.x/TILE,heightAt(memory.marker.x/TILE,memory.marker.y/TILE)+.5,memory.marker.y/TILE);if(p.z>1)return;octx.save();octx.setTransform(DPR,0,0,DPR,0,0);octx.fillStyle='#f6d58a';octx.strokeStyle='#1b2a31';octx.lineWidth=4;octx.font='bold 16px sans-serif';octx.textAlign='center';const text=memory.escorting?'Return to refuge':'◆ Mission destination';octx.strokeText(text,p.x,p.y-20);octx.fillText(text,p.x,p.y-20);octx.restore()};

function installCampaignUI(){document.title='Ariel of the Shahnameh';const style=document.createElement('style');style.textContent=`
#campaign{position:fixed;inset:0;z-index:1000;background:radial-gradient(ellipse at 80% 0,#394b4a,#122328 50%,#091318);color:#eee4cd;overflow:auto;padding:clamp(18px,4vw,52px);box-sizing:border-box}#campaign[hidden]{display:none}#campaign header{max-width:1200px;margin:auto;border-bottom:1px solid #90794b;padding-bottom:18px}#campaign h1{font:clamp(32px,5vw,58px) Georgia,serif;margin:8px 0;color:#efcf8b}#campaign .ey{letter-spacing:.2em;font-size:12px;text-transform:uppercase;color:#b8c8c2}#campaign .campaign-layout{display:grid;grid-template-columns:minmax(260px,1fr) minmax(300px,1.1fr);gap:32px;max-width:1200px;margin:24px auto}#campaign-list{max-height:58vh;overflow:auto;padding-right:12px}#campaign h3{font:20px Georgia,serif;color:#d5b982;margin:24px 0 12px}.memory-entry{display:flex;align-items:center;text-align:left;width:100%;gap:12px;padding:13px 10px;border:0;border-bottom:1px solid #34494b;background:transparent;color:#dbdfd3;font-size:14px;cursor:pointer}.memory-entry span{color:#d6b476;font-size:17px}.memory-entry b{flex:1}.memory-entry small{font-size:11px;color:#adbab5}.memory-entry.selected{background:#344747;box-shadow:inset 3px 0 #e2bc73}#campaign-detail{padding:28px;background:#172c31;border:1px solid #5d6656;align-self:start}#campaign-detail h2{font:34px Georgia,serif;color:#f1d59a;margin:14px 0}#campaign-detail p{line-height:1.65}#campaign button:disabled{opacity:.4;cursor:not-allowed}.campaign-tools{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.campaign-tools button{padding:10px 16px}.campaign-tools small{margin-left:auto;color:#bbcebf}#memory-hud{position:absolute;left:12px;top:185px;max-width:360px;padding:10px 12px;background:#132a2de8;border-left:2px solid #b99c62;z-index:12;color:#e6dbc0;font:13px/1.4 sans-serif;pointer-events:auto}#memory-hud b{display:block;color:#f3d493}#memory-hud small{color:#aebfb5}#memory-hud button{margin:5px 4px 0 0;background:#364a46;border:1px solid #8d805d;color:#f5e3bd;padding:7px;cursor:pointer}#memory-hud button:disabled{opacity:.5}#memory-objective{margin:7px 0}#obj{top:350px;max-width:330px}#objlist{max-height:22vh;overflow:auto}.memory-modal .card{display:block!important;max-width:790px!important;max-height:85vh;overflow:auto}.memory-modal #story-visual{display:none!important}.memory-modal #m-text{line-height:1.6}.memory-modal #m-acts{display:flex;flex-wrap:wrap;gap:8px}.memory-modal blockquote{font:28px Georgia,serif;color:#e9ce94;margin:22px 0}.narrator{color:#aac2be;font-size:13px}.memory-modal .big{font-size:16px;padding:12px 18px}.memory-modal #m-title{font-size:36px}@media(max-width:760px){#campaign .campaign-layout{grid-template-columns:1fr;gap:16px}#campaign-list{max-height:30vh}#campaign-detail{padding:18px}#memory-hud{top:170px;max-width:270px;font-size:11px}#obj{top:340px;max-width:280px}#campaign h1{font-size:32px}}`;
document.head.append(style);const shell=document.createElement('section');shell.id='campaign';shell.hidden=true;shell.innerHTML='<header><p class="ey">Nine acts · Sixty-two memories · One guardian</p><h1>Ariel of the Shahnameh</h1><p>“I was there. Let me tell you.”</p><div class="campaign-tools"><button class="big" id="resume-memory">Continue saved memory</button><button class="big ghost" id="return-memory">Return to game</button><small id="campaign-progress"></small></div></header><div class="campaign-layout"><nav id="campaign-list" aria-label="The 62 memories"></nav><article id="campaign-detail"></article></div>';document.body.append(shell);$('#resume-memory').onclick=resumeMemory;$('#return-memory').onclick=()=>{shell.hidden=true;paused=false};const hud=document.createElement('aside');hud.id='memory-hud';hud.innerHTML='<b id="memory-title"></b><small id="memory-age"></small><p id="memory-objective"></p><button id="bless-building">Bless building</button><small id="blessing-state"></small><button id="mission-action" hidden></button>';$('#game').append(hud);$('#bless-building').onclick=()=>{if(paused||gameOver)return;const a=ents.find(e=>e.type==='ariel'&&alive(e));if(!a){msg('Wait for Ariel to return.');return}blessingMode=!blessingMode;if(blessingMode){setSel([a.id]);msg('Click one of your buildings. The blessing moves there.')}else msg('Blessing selection cancelled.')};$('#mission-action').onclick=missionAction;$('#r-farr').title='Glory — priests at temples and heroic deeds';$('#b-hero small').textContent='Ariel & companions · H';}
// Distinct silhouettes for the new economy, rather than a row of renamed houses.
function cm(g,geometry,color,x=0,y=0,z=0){const m=new T3.Mesh(geometry,patch(new T3.MeshStandardMaterial({color,roughness:.86})));m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;g.add(m);return m}
const cb=(g,w,h,d,col,x=0,y=h/2,z=0)=>cm(g,new T3.BoxGeometry(w,h,d),col,x,y,z);
// A solid mountain ridge blocks movement; its southern rock face meets the cave mouth.
define('mountain','store',{name:'Mountain Ridge',w:16,h:8,hp:1000000,cost:undefined,drop:0,popc:0,los:0,desc:'Impassable mountain behind the settlement.'});
for(const [type,name] of [['ridge','Rocky Ridge'],['mesa','Sandstone Mesa'],['copse','Mountain Grove'],['stonefield','Stone Field'],['snowcrest','Snowy Crag']])define(type,'store',{name,w:3,h:3,hp:1000000,invul:1,cost:undefined,drop:0,popc:0,los:0,desc:'Natural terrain.'});
BUILD.mountain=g=>{const nx=32,nz=18,pos=[],colors=[],indices=[];for(let z=0;z<=nz;z++)for(let x=0;x<=nx;x++){const px=x/nx*16-8,pz=z/nz*8-4;const edge=Math.pow(Math.sin(Math.PI*x/nx)*Math.sin(Math.PI*z/nz),.55);const peaks=5.3+1.4*Math.sin(px*.85)+.8*Math.cos(pz*1.5);const h=Math.max(0,edge*peaks+.15*Math.sin(x*12+z*7)*edge);pos.push(px,h,pz);const c=new T3.Color(h>5.6?0xb6ad9b:0x837b68);c.multiplyScalar(.84+.17*Math.sin(h*9)+.08*Math.cos(px*3));colors.push(c.r,c.g,c.b)}for(let z=0;z<nz;z++)for(let x=0;x<nx;x++){const i=z*(nx+1)+x;indices.push(i,i+nx+1,i+1,i+1,i+nx+1,i+nx+2)}const geo=new T3.BufferGeometry();geo.setAttribute('position',new T3.Float32BufferAttribute(pos,3));geo.setAttribute('color',new T3.Float32BufferAttribute(colors,3));geo.setIndex(indices);geo.computeVertexNormals();const m=new T3.Mesh(geo,patch(new T3.MeshStandardMaterial({vertexColors:true,roughness:1,flatShading:true})));m.castShadow=m.receiveShadow=true;g.add(m);};
BUILD.cave=g=>{for(const [x,y,z,sx,sy,sz] of [[-1.35,1.15,-.3,1.1,1.7,1.7],[1.3,1.2,-.5,1.1,1.8,1.8],[0,2.45,-.6,1.8,.85,1.8],[-1.9,.5,-1.1,1,.8,1.4],[1.8,.5,-1.1,1,.9,1.4]]){const r=cm(g,new T3.DodecahedronGeometry(1,0),0x857d68,x,y,z);r.scale.set(sx,sy,sz)}const dark=new T3.Mesh(new T3.PlaneGeometry(2,2.4),new T3.MeshBasicMaterial({color:0x100e0c}));dark.position.set(0,1.15,-.35);g.add(dark);cb(g,2,.07,2.3,0x665b46,0,.02,.35);for(const x of [-1.15,1.15]){cb(g,.1,1.2,.1,0x4e3624,x,.6,1);cm(g,new T3.ConeGeometry(.12,.3,7),0xffad39,x,1.25,1)} };

BUILD.wall=g=>{cb(g,.85,1.4,.65,0xa18d68);for(const x of [-.3,0,.3])cb(g,.2,.25,.7,0xb4a37e,x,1.48)};
