  // Open-sided stone forge: the fire, anvil and tool bench remain visible from above.
  cb(g,2.95,.16,2.9,0x9a896d,0,.08,0);
  for(let i=0;i<19;i++){const x=((i*7)%17)/17*2.6-1.3,z=((i*11)%19)/19*2.5-1.25;cb(g,.3+(i%3)*.06,.025,.21, i%3===0?0xb19b78:0x85745d,x,.18,z)}
  cb(g,2.85,1.18,.26,0x9c8c71,0,.74,-1.27);
  cb(g,.22,.76,2.2,0x8e7c61,-1.36,.5,-.18);
  for(const x of [-1.22,1.22])for(const z of [-1.05,.15])cb(g,.19,2.02,.2,0x5d4330,x,1.11,z);
  for(const x of [-.69,.69]){const roof=cb(g,1.5,.16,1.53,0x694a32,x,2.22,-.62);roof.rotation.z=x<0?.25:-.25;cb(g,.1,.17,1.54,0x9b7650,x,2.1,-.62)}
  cb(g,.28,.3,1.56,0x4b3529,0,2.4,-.62);
