  const fire=new T3.Mesh(new T3.PlaneGeometry(.51,.38),new T3.MeshBasicMaterial({color:0xff842d,side:T3.DoubleSide}));fire.position.set(-.79,.66,-.103);g.add(fire);
  cb(g,.72,.13,.18,0xb09a75,-.79,1.16,-.1);
  cb(g,.53,1.55,.55,0x8b7a65,-.79,2.18,-.76);
  cb(g,.72,.16,.72,0xb09d7a,-.79,3,-.76);
  for(let i=0;i<4;i++){const coal=cm(g,new T3.DodecahedronGeometry(.09+(i%2)*.035,0),i%2?0xffa23e:0x3a2c24,-.98+i*.13,.42,-.07);coal.scale.y=.6}
  // The heavy anvil is the visual focus of the working yard.
  cm(g,new T3.CylinderGeometry(.3,.38,.58,9),0x6c4e32,.3,.48,.5);
  cb(g,.78,.18,.42,0x353c3e,.31,.85,.5);
  cb(g,.51,.12,.31,0x5b6260,.27,.99,.5);
  const horn=cm(g,new T3.ConeGeometry(.16,.47,9),0x42494b,.87,.87,.5);horn.rotation.z=-Math.PI/2;
  // Tools on the back rack, quenching trough and stacked iron stock.
  cb(g,1.06,.11,.13,0x604832,.73,1.27,-1.08);
  for(let i=0;i<4;i++){const x=.39+i*.23;cb(g,.055,.59-(i%2)*.12,.055,0x42494a,x,.91,-.97);cb(g,.17,.08,.08,0x353b3d,x,.62+(i%2)*.06,-.94)}
  cb(g,.62,.3,.48,0x67503b,1.02,.34,.68);cb(g,.48,.025,.34,0x295058,1.02,.5,.68);
  for(let i=0;i<3;i++)cb(g,.65,.06,.07,0x414749,-.87+i*.11,.25,.74+i*.13);
