const missionGuide=document.createElement('button');missionGuide.id='mission-guide';missionGuide.hidden=true;$('#memory-objective').after(missionGuide);
const plainMissionHUD=refreshMissionHUD;
refreshMissionHUD=function(){plainMissionHUD();if(!memory||!campaignActive)return;const s=PLANS[memory.id][memory.stage],guide=$('#mission-guide'),objective=$('#memory-objective');guide.hidden=true;if(s?.kind==='siamak'){objective.textContent=memory.duelStarted?'At the northern pass: Siamak is fighting the Black Demon. Watch the encounter.':'Send Prince Siamak to the gold mission marker at the northern pass.';guide.textContent='Find Prince Siamak';guide.hidden=!!memory.duelStarted;guide.onclick=()=>{const prince=byId.get(memory.siamakId);if(prince&&alive(prince)){setSel([prince.id]);centerOn(prince.x,prince.y)}}}else if(memory.id===2&&s?.kind==='build'&&s.type==='blacksmith'){if(age<2){const need=Math.max(0,AGEUP.cost.gold-res.gold);objective.textContent=ageQueued()?'Blacksmith workshop unlocks when the Town Center finishes advancing to the Age of Iron.':'Blacksmith is a building. Build a Fire Temple, gather '+need+' more gold, then advance at the Town Center to the Age of Iron.';guide.textContent='See Age of Iron';guide.onclick=()=>{const tc=ents.find(e=>e.type==='tc'&&e.team===0&&e.done&&alive(e));if(tc){setSel([tc.id]);centerOn(tc.x,tc.y);showUpgrade('ageup')}else msg('Build a Town Center to advance.','warn')}}else{objective.textContent='Build a Blacksmith workshop: select a villager, choose Blacksmith, then click clear ground. Cost: 150 wood and 80 gold.';guide.textContent='Place Blacksmith';guide.onclick=()=>{const v=ents.find(e=>e.type==='villager'&&e.team===0&&alive(e));if(!v){msg('Train a villager at the Town Center first.','warn');return}setSel([v.id]);centerOn(v.x,v.y);if(afford(DEF.blacksmith.cost))doAct('build:blacksmith');else msg('Blacksmith needs '+costLong(DEF.blacksmith.cost)+'.','warn')}}guide.hidden=false}}
const plainResumeMemory=resumeMemory;
resumeMemory=async function(){const saved=readSave();if(!saved||landscapeBusy)return;landscapeBusy=true;try{await prepareLandscape(saved.memory.id);plainResumeMemory();if(!memory||!campaignActive)return;if(memory.id>1&&!ents.some(e=>LANDSCAPE_TYPES.has(e.type))){addLandscapeForms(memory.id);saveMemory(false)}if(PLANS[memory.id]?.[memory.stage]?.kind==='siamak'){if(memory.duelResolved)showSiamakAftermath();else if(!memory.marker)beginStage();else refreshMissionHUD()}}finally{landscapeBusy=false}};
$('#resume-memory').onclick=resumeMemory;
// Weathered ridge surfaces, with several summits and irregular, tapered foothills.
BUILD.mountain=g=>{const nx=72,nz=40,pos=[],cols=[],idx=[],uv=[];for(let z=0;z<=nz;z++)for(let x=0;x<=nx;x++){const u=x/nx,v=z/nz,px=u*16-8,pz=v*8-4;const rim=Math.pow(Math.max(0,Math.sin(Math.PI*u)*Math.sin(Math.PI*v)),1.15);const spine=5.4+1.6*Math.sin(px*.65)+.8*Math.cos(px*1.45+pz*.4);const crags=.35*Math.sin(px*4.1+pz*2.6)+.2*Math.sin(px*7-pz*5);const h=Math.max(0,rim*(spine+crags));pos.push(px,h,pz);uv.push(u*3,v*2);const c=new T3.Color().setRGB(.27+h*.012,.245+h*.01,.20+h*.009);const strata=.93+.07*Math.sin(h*12+px*.5);c.multiplyScalar(strata);cols.push(c.r,c.g,c.b)}for(let z=0;z<nz;z++)for(let x=0;x<nx;x++){const i=z*(nx+1)+x;idx.push(i,i+nx+1,i+1,i+1,i+nx+1,i+nx+2)}const geo=new T3.BufferGeometry();geo.setAttribute('position',new T3.Float32BufferAttribute(pos,3));geo.setAttribute('color',new T3.Float32BufferAttribute(cols,3));geo.setAttribute('uv',new T3.Float32BufferAttribute(uv,2));geo.setIndex(idx);geo.computeVertexNormals();const rock=new T3.Mesh(geo,patch(new T3.MeshStandardMaterial({vertexColors:true,map:TX.rock,roughness:1})));rock.castShadow=rock.receiveShadow=true;g.add(rock);for(let i=0;i<18;i++){const x=Math.sin(i*13.7)*7,z=Math.cos(i*4.9)*3.5;const r=cm(g,new T3.DodecahedronGeometry(.18+(i%4)*.09,1),0x817c69,x,.1,z);r.scale.y=.65;}};
BUILD.ridge=g=>{for(const [x,z,h,r] of [[-.68,-.25,1.45,.8],[.35,-.48,2.2,.85],[.82,.55,1.18,.64],[-.55,.7,.8,.6]]){const rock=cm(g,new T3.DodecahedronGeometry(1,1),0x786f64,x,h*.39,z);rock.scale.set(r,h*.55,r*.8)}for(let i=0;i<7;i++){const x=Math.sin(i*2.9)*1.15,z=Math.cos(i*4.1)*1.08;const stone=cm(g,new T3.DodecahedronGeometry(.18+i%3*.06,0),0xaaa08a,x,.13,z);stone.scale.y=.55}};
BUILD.mesa=g=>{cm(g,new T3.CylinderGeometry(1.15,1.4,.46,7),0xa78968,0,.25,0);cm(g,new T3.CylinderGeometry(.91,1.17,.8,7),0xa17d5b,-.1,.78,-.1);cm(g,new T3.CylinderGeometry(.98,.99,.23,7),0xb69770,-.1,1.26,-.1);for(let i=0;i<5;i++){const a=i*2.7;const rock=cm(g,new T3.DodecahedronGeometry(.25+i%2*.1,0),0x8a745d,Math.cos(a)*1.1,.13,Math.sin(a)*1.1);rock.scale.y=.55}};
BUILD.copse=g=>{for(const [x,z,h] of [[-.8,-.6,2.2],[.65,-.72,2.65],[-.1,.65,1.8],[1,.55,1.4]]){cm(g,new T3.CylinderGeometry(.085,.12,h*.6,7),0x70523a,x,h*.3,z);const crown=cm(g,new T3.ConeGeometry(.4,h*.8,9),0x345c3f,x,h*.66,z);crown.scale.z=.9}for(let i=0;i<8;i++)cm(g,new T3.DodecahedronGeometry(.17,0),0x5f7452,Math.sin(i*7.1)*1.15,.1,Math.cos(i*5.2)*1.15)};
BUILD.stonefield=g=>{for(let i=0;i<11;i++){const a=i*2.43,r=.3+(i%4)*.31,x=Math.cos(a)*r,z=Math.sin(a)*r,s=.2+(i%5)*.09;const rock=cm(g,new T3.DodecahedronGeometry(s,0),i%3?0x948776:0xb0a38c,x,s*.43,z);rock.scale.set(1.1,.55,1.3)}};
BUILD.snowcrest=g=>{BUILD.ridge(g);for(const [x,y,z,r] of [[.35,1.8,-.48,.58],[-.68,1.15,-.25,.4],[.82,.9,.55,.35]]){const snow=cm(g,new T3.ConeGeometry(r,.38,7),0xdde4df,x,y,z);snow.rotation.y=.3}};

const slimTop=document.createElement('style');slimTop.textContent=`
:root{--bar:38px}
#top{height:38px!important;min-height:0;display:flex!important;flex-wrap:nowrap;gap:6px;padding:3px 7px;left:5px;right:5px;top:5px;border-width:1px;box-sizing:border-box;background:#172725ed;overflow-x:auto}
#top::before{display:none}#top .res{font-size:12px;gap:3px;flex:none}#top .res svg,#top .res img{width:15px;height:15px}
#top #age{font:12px Georgia,serif;margin-left:auto;max-width:none;white-space:nowrap;flex:none;padding:4px 6px;letter-spacing:0}
#top .tb{min-height:0;height:27px;padding:3px 6px;font-size:10px;flex:none;grid-column:auto}
#top .unit-shortcut{display:flex;flex-direction:row;min-height:0;gap:0}#top .unit-shortcut small{display:none}#top .unit-shortcut strong{font-size:10px;white-space:nowrap}
#top #clock{font-size:10px;flex:none}#top #b-menu{font-size:10px}
@media(max-width:620px){#top{gap:4px;height:34px!important}#top .res{font-size:11px}#top #age{font-size:10px}#top .tb{padding:2px 4px}#top #clock{display:none}}
`;document.head.append(slimTop);$('#b-idle strong').textContent='Idle workers';$('#b-army strong').textContent='Army';$('#b-hero strong').textContent='Heroes';
